#Requires -Version 5.1
# fix-obra-borra-android.ps1
# Causa real por la que Android borra la obra al adjuntar:
#
# 1. useEffect([form.fecha, misAsignaciones]) borraba obra_id cuando
#    misAsignaciones estaba vacia — en Android, al volver del file picker
#    el componente puede re-renderizarse con misAsignaciones=[] y el effect
#    ejecutaba setForm({obra_id:""}) aunque el usuario no habia cambiado la fecha.
#    FIX: guardia "misAsignaciones.length === 0 -> return"
#         y "form.obra_id &&" antes de borrarla
#
# 2. Si Android re-monta el componente, fetchData recarga el form desde Supabase.
#    Si la obra no estaba guardada en la BD todavia, vuelve vacia.
#    FIX: guardar obra_id en Supabase al inicio de uploadFiles, antes de subir
#         el archivo. Asi fetchData siempre trae el valor correcto.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix obra borrada en Android" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("misAsignaciones.length === 0")) { Write-Host "  OK: useEffect protegido (no borra con misAsignaciones vacio)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("form.obra_id &&")) { Write-Host "  OK: obra_id verificado antes de borrar" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("update({ obra_id: obraIdSnapshot })")) { Write-Host "  OK: obra guardada en BD antes del upload" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host '  git add "src\app\partes\[id]\page.tsx"'
Write-Host '  git commit -m "fix: Android - proteger useEffect obra_id + guardar en BD antes upload"'
Write-Host '  git push'
